from datetime import timedelta
from operator import add, sub
import six


# Python 2 rounds half away from zero (as taught in school) but Python 3
# uses "bankers' rounding" that rounds half towards the even number. We want
# consistent rounding and expect Python 2 style to be more familiar for users.
if six.PY2:
    _roundup = round
else:
    def _roundup(number, ndigits):
        precision = 10 ** (-1 * ndigits)
        if number % (0.5 * precision) == 0 and number % precision != 0:
            operator = add if number > 0 else sub
            number = operator(number, 0.1 * precision)
        return round(number, ndigits)


class TimeConverter(object):
    @classmethod
    def to_seconds(cls, time, round_to):
        if isinstance(time, timedelta):
            return time.total_seconds()
        return cls.timestr_to_secs(time, round_to=round_to)

    @classmethod
    def timestr_to_secs(cls, timestr, round_to=None):
        """Parses time like '1h 10s' or '42' and returns seconds."""
        if cls._is_string(timestr) or cls._is_number(timestr):
            for converter in cls._number_to_secs, cls._time_string_to_secs:
                secs = converter(timestr)
                if secs is not None:
                    if round_to is None:
                        return secs
                    else:
                        return cls._roundup(secs, round_to)
        elif timestr is None:
            return timestr
        raise ValueError("Invalid time string '%s'." % timestr)

    @classmethod
    def normalize(cls, string, caseless=True, spaceless=True):
        """Normalizes given string according to given spec.

        By default string is turned to lower case and all whitespace is removed.
        """
        empty = u'' if cls._is_unicode(string) else b''
        if spaceless:
            string = empty.join(string.split())
        if caseless:
            string = string.lower()

        return string

    @classmethod
    def _normalize_timestr(cls, timestr):
        timestr = cls.normalize(timestr)
        for specifier, aliases in [('x', ['millisecond', 'millisec', 'millis',
                                          'msec', 'ms']),
                                   ('s', ['second', 'sec']),
                                   ('m', ['minute', 'min']),
                                   ('h', ['hour']),
                                   ('d', ['day'])]:
            plural_aliases = [a + 's' for a in aliases if not a.endswith('s')]
            for alias in plural_aliases + aliases:
                if alias in timestr:
                    timestr = timestr.replace(alias, specifier)
        return timestr

    @staticmethod
    def _roundup(number, ndigits=0, return_type=None):
        """Rounds number to the given number of digits.

        Numbers equally close to a certain precision are always rounded away from
        zero. By default return value is float when ``ndigits`` is positive and
        int otherwise, but that can be controlled with ``return_type``.

        With the built-in ``round()`` rounding equally close numbers as well as
        the return type depends on the Python version.
        """
        result = _roundup(number, ndigits)
        if not return_type:
            return_type = float if ndigits > 0 else int
        return return_type(result)

    @staticmethod
    def _number_to_secs(number):
        try:
            return float(number)
        except ValueError:
            return None

    @classmethod
    def _time_string_to_secs(cls, timestr):
        timestr = cls._normalize_timestr(timestr)
        millis = secs = mins = hours = days = 0
        sign, timestr = cls._calculate_sign_and_adjust_time_string(timestr)
        temp = []
        for c in timestr:
            try:
                components = cls._calculate_components(
                    c, days, hours, millis, mins, secs, temp)
                days, hours, millis, mins, secs, temp = components
            except ValueError:
                return None
        if temp:
            return None
        return sign * (millis / 1000
                       + secs +
                       + mins * 60
                       + hours * 60 * 60
                       + days * 60 * 60 * 24)

    @staticmethod
    def _calculate_sign_and_adjust_time_string(timestr):
        if timestr[0] == '-':
            sign = -1
            timestr = timestr[1:]
        else:
            sign = 1
        return sign, timestr

    @staticmethod
    def _calculate_components(c, days, hours, millis, mins, secs, temp):
        if c == 'x':
            millis = float(''.join(temp))
            temp = []
        elif c == 's':
            secs = float(''.join(temp))
            temp = []
        elif c == 'm':
            mins = float(''.join(temp))
            temp = []
        elif c == 'h':
            hours = float(''.join(temp))
            temp = []
        elif c == 'd':
            days = float(''.join(temp))
            temp = []
        else:
            temp.append(c)
        return days, hours, millis, mins, secs, temp

    @staticmethod
    def _is_string(item):
        return isinstance(item, six.string_types)

    @staticmethod
    def _is_number(item):
        return isinstance(item, (int, float))

    @staticmethod
    def _is_unicode(item):
        return isinstance(item, str)
